#include <stdio.h>
#include <string.h>

/* Khớp bộ lọc MQTT: + khớp đúng một cấp, # khớp mọi cấp còn lại (đặt ở cuối). */
static int khop(const char *f, const char *t) {
    if (f[0] == '#') return 1;
    if (f[0] == '\0') return t[0] == '\0';
    if (t[0] == '\0') return 0;
    size_t lf = strcspn(f, "/"), lt = strcspn(t, "/");
    int giong = (lf == 1 && f[0] == '+') || (lf == lt && strncmp(f, t, lf) == 0);
    if (!giong) return 0;
    f += lf;
    t += lt;
    if (f[0] == '/') {
        if (t[0] != '/') return 0;
        return khop(f + 1, t + 1);
    }
    return khop(f, t);
}

int main(void) {
    char loc[256], chu_de[256];
    if (scanf("%255s %255s", loc, chu_de) != 2) return 1;
    printf(khop(loc, chu_de) ? "yes\n" : "no\n");
    return 0;
}
